"""P9 -- endpoint targets generated by the TRANSFORM, never by identity.

The rule this module exists to enforce (§34): once a rigid patch hypothesis
is accepted,

    y_hat_i = R_p x_i + t_p

for every Gaussian in the patch.  The target cloud was used to infer the
physical transform and its job ends there.  Substituting a nearest target
Gaussian would reintroduce the identity assumption that does not hold between
two independently trained models -- and would hand flow matching the
correspondence problem it is not supposed to be solving.

A Gaussian in several accepted patches gets a consensus only when those
patches belong to the same transform-consistency component (§35).  Otherwise
it is AMBIGUOUS.  Averaging two genuinely different motions produces a third
motion that neither patch proposed and that nothing in the scene performs.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any

import torch

from utils.se3_hypothesis_consistency import robust_se3_consensus, se3_exp, se3_log

LABEL_STATIC = 0
LABEL_DYNAMIC = 1
LABEL_AMBIGUOUS = 2
EPS = 1.0e-12


@dataclass
class TransformAssignment:
    """Per-Gaussian resolved transform, or an explicit refusal to resolve."""

    rotation: torch.Tensor       # [N, 3, 3]
    translation: torch.Tensor    # [N, 3]
    assigned: torch.Tensor       # [N] bool -- a transform was resolved
    ambiguous: torch.Tensor      # [N] bool -- conflicting components
    component: torch.Tensor      # [N] winning component id, -1 if none
    patch_count: torch.Tensor    # [N] accepted patches covering this Gaussian
    stats: dict[str, Any] = field(default_factory=dict)


@torch.no_grad()
def assign_accepted_patch_transforms_to_gaussians(
    num_gaussians: int,
    patch_indices: torch.Tensor,
    patch_valid: torch.Tensor,
    accepted: torch.Tensor,
    component: torch.Tensor,
) -> tuple[list[list[int]], torch.Tensor]:
    """Which accepted patches cover each Gaussian.

    Returns ``(patches per Gaussian, coverage count)``.  Coverage is built
    from patch membership rather than from anchors alone, because a patch's
    transform is a claim about all of its points.
    """
    indices = torch.as_tensor(patch_indices).detach().cpu().long()
    valid = torch.as_tensor(patch_valid).detach().cpu().bool()
    accepted = torch.as_tensor(accepted).detach().cpu().bool()
    component = torch.as_tensor(component).detach().cpu().long()

    membership: list[list[int]] = [[] for _ in range(int(num_gaussians))]
    for patch in range(int(indices.shape[0])):
        if not bool(accepted[patch]) or int(component[patch]) < 0:
            continue
        for slot in range(int(indices.shape[1])):
            if bool(valid[patch, slot]):
                membership[int(indices[patch, slot])].append(patch)
    count = torch.tensor([len(m) for m in membership], dtype=torch.long)
    return membership, count


@torch.no_grad()
def resolve_overlapping_patch_transforms(
    num_gaussians: int,
    membership: list[list[int]],
    rotation: torch.Tensor,
    translation: torch.Tensor,
    component: torch.Tensor,
    *,
    weights: torch.Tensor | None = None,
) -> TransformAssignment:
    """§35: consensus within one component, AMBIGUOUS across components."""
    rotation = torch.as_tensor(rotation).detach().float().cpu()
    translation = torch.as_tensor(translation).detach().float().cpu()
    component = torch.as_tensor(component).detach().long().cpu()
    tangent = se3_log(rotation, translation)
    weights = torch.ones(int(rotation.shape[0])) if weights is None else weights.float().cpu()

    out_rotation = torch.eye(3).repeat(int(num_gaussians), 1, 1)
    out_translation = torch.zeros((int(num_gaussians), 3))
    assigned = torch.zeros(int(num_gaussians), dtype=torch.bool)
    ambiguous = torch.zeros(int(num_gaussians), dtype=torch.bool)
    winning = torch.full((int(num_gaussians),), -1, dtype=torch.long)
    count = torch.zeros(int(num_gaussians), dtype=torch.long)

    for gaussian, patches in enumerate(membership):
        count[gaussian] = len(patches)
        if not patches:
            continue
        components = component[torch.tensor(patches, dtype=torch.long)]
        unique = torch.unique(components)
        if int(unique.numel()) != 1:
            # Two accepted patches claim different motions for this Gaussian.
            # There is no answer that is true to both.
            ambiguous[gaussian] = True
            continue
        picked = torch.tensor(patches, dtype=torch.long)
        centre = robust_se3_consensus(tangent[picked], weights[picked])
        r, t = se3_exp(centre[None, :])
        out_rotation[gaussian] = r[0]
        out_translation[gaussian] = t[0]
        assigned[gaussian] = True
        winning[gaussian] = int(unique[0])

    return TransformAssignment(
        rotation=out_rotation,
        translation=out_translation,
        assigned=assigned,
        ambiguous=ambiguous,
        component=winning,
        patch_count=count,
        stats={
            "assigned_fraction": float(assigned.float().mean()),
            "ambiguous_fraction": float(ambiguous.float().mean()),
            "covered_fraction": float((count > 0).float().mean()),
        },
    )


@torch.no_grad()
def generate_endpoint_targets(
    source_xyz: torch.Tensor,
    assignment: TransformAssignment,
) -> tuple[torch.Tensor, torch.Tensor]:
    """``y_hat_i = R_i x_i + t_i``; returns ``(targets, supervised)``.

    Unassigned Gaussians keep their own position and are reported as NOT
    supervised rather than being given a zero displacement. A fabricated
    "did not move" target is indistinguishable downstream from a measured
    one, and flow matching would learn it as fact.
    """
    source_xyz = torch.as_tensor(source_xyz).detach().float()
    rotation = assignment.rotation.to(source_xyz.device)
    translation = assignment.translation.to(source_xyz.device)
    moved = torch.einsum("nij,nj->ni", rotation, source_xyz) + translation
    supervised = assignment.assigned.to(source_xyz.device)
    return torch.where(supervised[:, None], moved, source_xyz), supervised


@torch.no_grad()
def generate_forward_fm_pairs(
    source_xyz: torch.Tensor,
    assignment: TransformAssignment,
) -> dict[str, torch.Tensor]:
    """``x_i -> T_i x_i`` training pairs (§40). No target Gaussian identity."""
    targets, supervised = generate_endpoint_targets(source_xyz, assignment)
    source_xyz = torch.as_tensor(source_xyz).detach().float()
    return {
        "source": source_xyz[supervised],
        "target": targets[supervised],
        "velocity": (targets - source_xyz)[supervised],
        "index": supervised.nonzero(as_tuple=True)[0],
        "supervised": supervised,
    }


@torch.no_grad()
def generate_backward_fm_pairs(
    target_xyz: torch.Tensor,
    assignment: TransformAssignment,
) -> dict[str, torch.Tensor]:
    """Backward pairs from an INDEPENDENTLY estimated backward assignment.

    §39: the backward transform must be inferred from the two endpoint clouds
    in its own right, never constructed as the analytic inverse of the
    forward one.  ``T^{T->0} T^{0->T} ~ I`` is then a validation condition
    with real content; built as an inverse it would hold by construction and
    test nothing.
    """
    return generate_forward_fm_pairs(target_xyz, assignment)


@torch.no_grad()
def verify_inverse_consistency(
    forward: TransformAssignment,
    backward_rotation: torch.Tensor,
    backward_translation: torch.Tensor,
) -> dict[str, torch.Tensor]:
    """§39's validation: is ``T_back . T_fwd`` close to the identity?"""
    r_f = forward.rotation
    t_f = forward.translation
    r_b = torch.as_tensor(backward_rotation).detach().float().to(r_f.device)
    t_b = torch.as_tensor(backward_translation).detach().float().to(t_f.device)
    composed_r = r_b @ r_f
    composed_t = torch.einsum("nij,nj->ni", r_b, t_f) + t_b
    identity = torch.eye(3, device=r_f.device)[None].expand_as(composed_r)
    return {
        "rotation_error": torch.linalg.matrix_norm(composed_r - identity),
        "translation_error": torch.linalg.norm(composed_t, dim=1),
        "tangent_error": torch.linalg.norm(se3_log(composed_r, composed_t), dim=1),
    }


@torch.no_grad()
def physical_labels(
    motion_posterior_dynamic: torch.Tensor,
    assignment: TransformAssignment,
    *,
    render_prefers_dynamic: torch.Tensor | None = None,
) -> torch.Tensor:
    """§36's decision TREE -- no weighted score anywhere in it.

    DYNAMIC requires every physical stage to have passed: the static
    hypothesis rejected, a transform resolved from a metric- and
    SE(3)-validated patch inside a coherent component, and rendering
    preferring it where rendering was run.  Anything else that is not clearly
    static is AMBIGUOUS, which §65 makes an acceptable answer.
    """
    dynamic_posterior = torch.as_tensor(motion_posterior_dynamic).detach().float().cpu()
    static_hypothesis_holds = dynamic_posterior <= 0.5

    label = torch.full((int(dynamic_posterior.numel()),), LABEL_AMBIGUOUS, dtype=torch.long)
    supported = assignment.assigned.cpu()
    if render_prefers_dynamic is not None:
        supported = supported & torch.as_tensor(render_prefers_dynamic).detach().bool().cpu()

    label[static_hypothesis_holds & ~supported] = LABEL_STATIC
    label[~static_hypothesis_holds & supported] = LABEL_DYNAMIC
    label[assignment.ambiguous.cpu()] = LABEL_AMBIGUOUS
    return label
